I need help writing a function that merges two sorted lists into a single sorted list. The function should be written in C++. Here are the unit tests:

// Test 1: merge({1, 3, 5}, {2, 4, 6}) returns {1, 2, 3, 4, 5, 6}
// Test 2: merge({1, 2, 3}, {}) returns {1, 2, 3}
// Test 3: merge({}, {4, 5, 6}) returns {4, 5, 6}
// Test 4: merge({1, 3, 5}, {1, 3, 5}) returns {1, 1, 3, 3, 5, 5}

answer:
Here's a C++ function that merges two sorted lists into a single sorted list, along with the unit tests as requested:

```cpp
#include <vector>
#include <algorithm>
#include <cassert>

std::vector<int> merge(const std::vector<int>& list1, const std::vector<int>& list2) {
    std::vector<int> merged;
    merged.reserve(list1.size() + list2.size());
    int i = 0, j = 0;
    while (i < list1.size() && j < list2.size()) {
        if (list1[i] <= list2[j]) {
            merged.push_back(list1[i]);
            ++i;
        } else {
            merged.push_back(list2[j]);
            ++j;
        }
    }
    merged.insert(merged.end(), list1.begin() + i, list1.end());
    merged.insert(merged.end(), list2.begin() + j, list2.end());
    return merged;
}

// Unit tests
int main() {
    // Test 1
    assert(merge({1, 3, 5}, {2, 4, 6}) == std::vector<int>{1, 2, 3, 4, 5, 6});
    // Test 2
    assert(merge({1, 2, 3}, {}) == std::vector<int>{1, 2, 3});
    // Test 3
    assert(merge({}, {4, 5, 6}) == std::vector<int>{4, 5, 6});
    // Test 4
    assert(merge({1, 3, 5}, {1, 3, 5}) == std::vector<int>{1, 1, 3, 3, 5, 5});
    return 0;
}
```
This function uses a two-pointer technique to merge the two lists while maintaining the sorted order.

